// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    Signer maker;
    DummyToken base;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        maker = new Signer();
        base = new DummyToken();
    }

    function testFuzz_property(uint256 strike, uint256 duration, address to) public {
        vm.assume(to != address(0) && to != address(maker));
        duration = bound(duration, 1 days, 9_999 days);
        strike = bound(strike, 0, type(uint128).max);

        vm.warp(1_000);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: true,
            isLong: true,
            baseAsset: address(base),
            strike: strike,
            premium: 0,
            duration: duration,
            expiration: block.timestamp + 100,
            nonce: 0,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new PuttyV2.ERC20Asset[](0),
            erc721Assets: new PuttyV2.ERC721Asset[](0)
        });

        uint256[] memory noIds = new uint256[](0);

        vm.prank(address(maker));
        c.fillOrder(order, "", noIds);

        uint256 makerPositionId = uint256(c.hashOrder(order));

        vm.prank(address(maker));
        c.transferFrom(address(maker), to, makerPositionId);

        assertTrue(c.ownerOf(makerPositionId) == to);
    }
}

// IERC1271 wallet: signs its own orders so fillOrder's signature check passes.
contract Signer {
    function isValidSignature(bytes32, bytes memory) external view returns (bytes4) {
        return this.isValidSignature.selector;
    }
}

// Minimal token stand-in: any call succeeds with empty returndata, which
// SafeTransferLib accepts as success, and it has code so baseAsset check passes.
contract DummyToken {
    fallback() external payable {}
}
